      "type": "object"
    },
    "CheckOutcome": {
      "enum": [
        "pass",
        "fail",
        "not_applicable"
      ],
      "title": "CheckOutcome",
      "type": "string"
    },
    "QualityCheckModel": {
      "properties": {
        "explanation": {
          "title": "Explanation",
          "type": "string"
        },
        "outcome": {
          "$ref": "#/$defs/CheckOutcome"
        }
      },
      "required": [
        "explanation",
        "outcome"
      ],
      "title": "QualityCheckModel",
      "type": "object"
    }
  },
  "properties": {
    "summary": {
      "title": "Summary",
      "type": "string"
    },
    "checks": {
      "$ref": "#/$defs/AnalyzeResultChecks"
